typedef unsigned long VAddr; // Virtual Address

// Simplified Relocation Entry (ELF Rela structure basis)
struct Rela {
    VAddr r_offset;     // Location to modify (P)
    int r_type;         // Relocation type (e.g., R_X86_64_PC32)
    long r_addend;      // Constant offset (A)
    VAddr sym_value;    // Symbol's final value (S)
};

// Linker/Loader calculation logic (Varies by r_type)

// Example 1: Absolute 64-bit Address (R_X86_64_64)
VAddr Absolute_Fixup(struct Rela R) {
    return R.sym_value + R.r_addend; // S + A
}

// Example 2: PC-Relative 32-bit Address (R_X86_64_PC32)
long PCRelative_Fixup(struct Rela R) {
    return R.sym_value + R.r_addend - R.r_offset; // S + A - P
}

// The result is written to memory at address P.
